// We use the Verus specification and Vec library.
use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

    /// decode_shift: Given a Vec<char> s of lowercase letters 'a'..'z',
    /// produce a new Vec<char> t of the same length where each character
    /// is shifted left by 5 positions in the alphabet (mod 26).
    ///
    /// For each i < s.len(),
    ///    let x = s[i] as u8;
    ///    t[i] as u8 == ((x + 26u8 - 5u8 - ('a' as u8)) % 26u8) + ('a' as u8)
    fn decode_shift(s: Vec<char>) -> (t: Vec<char>)
        ensures
            // same length
            t.len() == s.len()
        ensures
            // for each position, the Caesar‐decoded formula holds
            forall |i: usize|
                i < s.len() ==>
                let x: u8 = s[i] as u8;
                (t[i] as u8) == ((x + 26u8 - 5u8 - ('a' as u8)) % 26u8) + ('a' as u8)
    {
        // We'll build the result vector element by element.
        let mut t = Vec::new();
        let mut i: usize = 0;
        // Loop over all indices 0..s.len()
        while i < s.len() {
            invariant i <= s.len();
            invariant t.len() == i;
            invariant forall |j: usize|
                j < i ==>
                // the prefix of t is correctly decoded
                let xj: u8 = s[j] as u8;
                (t[j] as u8) == ((xj + 26u8 - 5u8 - ('a' as u8)) % 26u8) + ('a' as u8);

            {
                // read the i-th character from s
                let c = s[i];
                // input characters are guaranteed lowercase
                assert!(c >= 'a' && c <= 'z');
                // compute its ASCII code
                let x: u8 = c as u8;
                // shift left by 5 within 0..25, then add back 'a'
                let y: u8 = (x + 26u8 - 5u8 - ('a' as u8)) % 26u8;
                let r_u8: u8 = y + ('a' as u8);
                let r: char = r_u8 as char;
                // r must again be a lowercase letter
                assert!(r >= 'a' && r <= 'z');
                // push the decoded char
                t.push(r);
            }

            i += 1;
        }

        // now t.len() == s.len() and by the loop invariant
        // we have for all i < s.len() the required formula
        t
    }

} // end of verus!